<style id="queue-monitor-theme-css">
html[data-theme="dark"]{color-scheme:dark;background:#0b1220}html[data-theme="dark"] body{background:#0b1220!important;color:#e5eaf3!important}
html[data-theme="dark"] .qm-topbar,html[data-theme="dark"] .qm-panel,html[data-theme="dark"] .qm-connection-card,html[data-theme="dark"] .qm-filter-panel,html[data-theme="dark"] .qm-stat-card,html[data-theme="dark"] .qm-jobs-panel,html[data-theme="dark"] .qm-widget-preferences,html[data-theme="dark"] .qm-analytics-panel,html[data-theme="dark"] .qm-health-summary,html[data-theme="dark"] .qm-health-overview,html[data-theme="dark"] .qm-detail-card,html[data-theme="dark"] .qm-capacity-card,html[data-theme="dark"] .qm-worker-card{background:#151f30!important;border-color:#2b394d!important;color:#e5eaf3!important}
html[data-theme="dark"] .qm-heading h1,html[data-theme="dark"] .qm-section-heading h2,html[data-theme="dark"] .qm-panel-heading h3,html[data-theme="dark"] .qm-stat-card>strong,html[data-theme="dark"] .qm-detail-list dd,html[data-theme="dark"] .qm-health-metric strong,html[data-theme="dark"] .qm-diagnostic-item strong{color:#e5eaf3!important}
html[data-theme="dark"] .qm-table th{background:#101a29!important;color:#aab8cc!important}html[data-theme="dark"] .qm-table td,html[data-theme="dark"] .qm-compare-table td{color:#cbd5e1!important;border-color:#2b394d!important}
html[data-theme="dark"] input,html[data-theme="dark"] select,html[data-theme="dark"] textarea{background:#101a29!important;color:#e5eaf3!important;border-color:#39485e!important}
html[data-theme="dark"] .qm-muted{color:#9aa9bd!important}html[data-theme="dark"] .qm-bulk-toolbar,html[data-theme="dark"] .qm-capacity-card,html[data-theme="dark"] .qm-worker-card{background:#111b2b!important}
html[data-theme="dark"] .qm-detail-code,html[data-theme="dark"] pre{background:#0a1220!important;color:#dbe5f2!important;border-color:#2b394d!important}
#queue-monitor-theme-picker{position:fixed;right:18px;bottom:18px;z-index:99999;display:flex;align-items:center;gap:8px;padding:9px 11px;border:1px solid #d9e0ea;border-radius:12px;background:#fff;color:#263348;box-shadow:0 8px 28px #15223826;font:600 12px/1.2 system-ui,sans-serif}
#queue-monitor-theme-picker select{border:0;background:transparent;color:inherit;font:inherit;outline:none;cursor:pointer}html[data-theme="dark"] #queue-monitor-theme-picker{background:#182437;color:#e5eaf3;border-color:#39485e}
</style>
<script>
(function(){var root=document.documentElement,key='queue-monitor-theme',labels=['Day','Night','System'],allowed=['light','dark','system'];function system(){return matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}function read(){try{var v=localStorage.getItem(key);return allowed.indexOf(v)>=0?v:'system'}catch(e){return 'system'}}var preference=read();function apply(){var v=preference==='system'?system():preference;root.dataset.theme=v;root.style.colorScheme=v}function mount(){apply();if(document.getElementById('queue-monitor-theme-picker'))return;var w=document.createElement('label');w.id='queue-monitor-theme-picker';w.innerHTML='<span aria-hidden="true">◐</span><select aria-label="Theme"><option value="light">'+labels[0]+'</option><option value="dark">'+labels[1]+'</option><option value="system">'+labels[2]+'</option></select>';var s=w.querySelector('select');s.value=preference;s.addEventListener('change',function(){preference=s.value;try{localStorage.setItem(key,preference)}catch(e){}apply()});document.body.appendChild(w)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();var m=matchMedia('(prefers-color-scheme: dark)');if(m.addEventListener)m.addEventListener('change',function(){if(preference==='system')apply()});else m.addListener(function(){if(preference==='system')apply()})})();
</script>